export interface VersionRecord {
  buildNum: string; // CI 构建号（主标识，用于归档/匹配/切换）
  tag: string; // git tag 派生（仅展示用，不参与功能逻辑）
  sdkVersion: string;
  publishedAt: string;
  commitHash: string;
  commitMessage: string;
  pipelineId: string;
  publisher: string;
  releasePath: string;
  resources: Record<string, string>; // 逻辑名 → 资源文件名（相对路径，boot script 拼 ./releases/{buildNum}/assets/{file}）
}

export interface VersionManifest {
  latest: string;
  updatedAt: string;
  versions: VersionRecord[];
}

const VERSION_STORAGE_KEY = 'viewer_version';

/**
 * 获取当前页面已加载的版本
 * 策略：检测已加载 script 的 src 路径 → localStorage → 默认 'latest'
 */
export function getCurrentVersion(): string {
  // 方法1：从已加载脚本 URL 中提取 releases/{buildNum}/ 路径
  const scripts = document.querySelectorAll<HTMLScriptElement>('script[src]');
  for (let i = 0; i < scripts.length; i++) {
    const match = scripts[i].src.match(/\/releases\/(\d+)\//);
    if (match) return match[1];
  }

  // 方法2：回退到 localStorage
  try {
    const stored = localStorage.getItem(VERSION_STORAGE_KEY);
    if (stored) return stored;
  } catch {
    /* 静默降级 */
  }

  return 'latest';
}

/**
 * 从 COS 加载版本清单 
 * @returns 版本清单，加载失败时返回 null
 */
export async function fetchVersions(): Promise<VersionManifest | null> {
  try {
    // 加时间戳查询参数强制绕过浏览器/CDN 缓存
    const res = await fetch(`./versions.json?t=${Date.now()}`, { cache: 'no-store' });
    if (!res.ok) return null;
    const data: VersionManifest = await res.json();
    return data;
  } catch {
    return null;
  }
}

/**
 * 切换到指定版本
 * @param version 目标版本 buildNum，传 null/空字符串表示切回 latest
 */
export function switchVersion(version: string | null): void {
  if (version) {
    try {
      localStorage.setItem(VERSION_STORAGE_KEY, version);
    } catch {
      /* 静默降级 */
    }
  } else {
    try {
      localStorage.removeItem(VERSION_STORAGE_KEY);
    } catch {
      /* 静默降级 */
    }
  }

  // 将 version 放入 hash 查询字符串，避免 location.search 与 hash 路由自身的 ? 冲突
  const hash = window.location.hash || '#/';
  const qIdx = hash.indexOf('?');
  const hashPath = qIdx >= 0 ? hash.slice(0, qIdx) : hash;
  const hashQuery = qIdx >= 0 ? hash.slice(qIdx + 1) : '';
  const params = new URLSearchParams(hashQuery);
  if (version) {
    params.set('version', version);
  } else {
    params.delete('version');
  }
  const qs = params.toString();
  const newHash = hashPath + (qs ? '?' + qs : '');

  // 保留 origin + pathname，丢弃旧 search，更新 hash
  // 仅改 hash 不会触发整页刷新，需 replaceState 更新 URL 后显式 reload
  const newUrl = window.location.origin + window.location.pathname + newHash;
  window.history.replaceState(null, '', newUrl);
  window.location.reload();
}
